import{_ as a,o as e,c as r,a2 as t}from"./chunks/framework.DA69LXMH.js";const p=JSON.parse('{"title":"Integrações (Discord, Áudio Virtual & Notion)","description":"","frontmatter":{},"headers":[],"relativePath":"recursos/integracoes.md","filePath":"recursos/integracoes.md"}'),s={name:"recursos/integracoes.md"};function i(d,o,n,c,l,m){return e(),r("div",null,[...o[0]||(o[0]=[t('<h1 id="integracoes-discord-audio-virtual-notion" tabindex="-1">Integrações (Discord, Áudio Virtual &amp; Notion) <a class="header-anchor" href="#integracoes-discord-audio-virtual-notion" aria-label="Permalink to &quot;Integrações (Discord, Áudio Virtual &amp; Notion)&quot;">​</a></h1><p>O <strong>EchoBot</strong> conecta-se aos canais de comunicação e ferramentas de anotação que você já utiliza na sua mesa de RPG, mantendo sua crônica acessível e compartilhável.</p><hr><h2 id="🎧-bot-de-voz-do-discord-voice-bridge" tabindex="-1">🎧 Bot de Voz do Discord (Voice Bridge) <a class="header-anchor" href="#🎧-bot-de-voz-do-discord-voice-bridge" aria-label="Permalink to &quot;🎧 Bot de Voz do Discord (Voice Bridge)&quot;">​</a></h2><p>O EchoBot inclui um serviço nativo Node.js desenvolvido especificamente para canais de voz do Discord:</p><h3 id="comandos-slash" tabindex="-1">Comandos Slash <a class="header-anchor" href="#comandos-slash" aria-label="Permalink to &quot;Comandos Slash&quot;">​</a></h3><ul><li><strong><code>/entrar [sessao_id] [duracao_chunk]</code>:</strong><ul><li>O bot conecta-se imediatamente ao canal de voz onde você está.</li><li>O parâmetro <code>sessao_id</code> vincula a gravação diretamente a uma sessão aberta no EchoBot.</li><li>O bot captura o áudio de cada participante em faixas separadas, convertendo em tempo real para o formato ultraleve <strong>Ogg/Opus</strong>.</li></ul></li><li><strong><code>/sair</code>:</strong><ul><li>O bot desconecta da chamada e dispara a transmissão e finalização dos áudios no painel do EchoBot.</li></ul></li></ul><h3 id="modo-gravador-de-podcast-standalone" tabindex="-1">Modo Gravador de Podcast Standalone <a class="header-anchor" href="#modo-gravador-de-podcast-standalone" aria-label="Permalink to &quot;Modo Gravador de Podcast Standalone&quot;">​</a></h3><p>Precisa gravar uma chamada avulsa sem criar previamente uma sessão de campanha?</p><ul><li>Execute <code>/entrar</code> sem especificar um ID de sessão.</li><li>O bot gravará todas as faixas individuais diretamente na pasta local <code>/recordings</code> com um arquivo descritor <code>metadata.json</code>, funcionando como um gravador de podcast multitrack independente.</li></ul><hr><h2 id="🎙️-transmissao-de-vozes-de-npcs-vb-cable-voicemeeter" tabindex="-1">🎙️ Transmissão de Vozes de NPCs (VB-Cable / VoiceMeeter) <a class="header-anchor" href="#🎙️-transmissao-de-vozes-de-npcs-vb-cable-voicemeeter" aria-label="Permalink to &quot;🎙️ Transmissão de Vozes de NPCs (VB-Cable / VoiceMeeter)&quot;">​</a></h2><p>Você pode transmitir as falas sintetizadas dos NPCs (via Kokoro TTS ou ElevenLabs) diretamente para os seus amigos na chamada do Discord:</p><ol><li>Instale um driver gratuito de cabo de áudio virtual (recomendado: <a href="https://vb-audio.com/Cable/" target="_blank" rel="noreferrer">VB-Audio Virtual Cable</a>).</li><li>No Windows, configure o reprodutor de áudio ou defina o <strong>CABLE Input</strong> como saída de som do sistema.</li><li>No Discord, em <strong>Configurações de Voz &amp; Vídeo</strong>, selecione <strong>CABLE Output</strong> como seu dispositivo de entrada (Microfone).</li><li><em>(Dica com VoiceMeeter):</em> Se desejar falar no seu microfone real e tocar a voz dos NPCs ao mesmo tempo, use o VoiceMeeter para mixar seu microfone físico + o CABLE Input no mesmo canal de saída.</li><li>Agora, sempre que você clicar em reproduzir a fala de um NPC ou a narração épica no EchoBot, todos os jogadores ouvirão com alta fidelidade na chamada!</li></ol><hr><h2 id="📑-integracao-com-notion-so" tabindex="-1">📑 Integração com Notion.so <a class="header-anchor" href="#📑-integracao-com-notion-so" aria-label="Permalink to &quot;📑 Integração com Notion.so&quot;">​</a></h2><p>Sincronize automaticamente os resumos e diários das suas partidas com o seu banco de notas do Notion:</p><ol><li>Em <strong>Configurações ➔ Integrações</strong>, insira sua <strong>Chave de Integração do Notion (Internal Integration Token)</strong> e o <strong>ID da Página/Database</strong>.</li><li>Na página de detalhes da sessão, clique em <strong>Exportar ➔ Notion</strong>.</li><li>O EchoBot criará uma página estilizada contendo: <ul><li>Título, data e duração da sessão.</li><li>Diário técnico organizado por categorias (NPCs, Locais, Itens, Quests e XP).</li><li>Roteiro completo da história.</li></ul></li></ol><hr><h2 id="📄-exportacao-multiformato-importacao-de-transcricoes" tabindex="-1">📄 Exportação Multiformato &amp; Importação de Transcrições <a class="header-anchor" href="#📄-exportacao-multiformato-importacao-de-transcricoes" aria-label="Permalink to &quot;📄 Exportação Multiformato &amp; Importação de Transcrições&quot;">​</a></h2><ul><li><strong>PDF Premium:</strong> Gera um documento elegante com tipografia de fantasia, bordas decorativas e organização em duas colunas, ideal para imprimir ou compartilhar com o grupo.</li><li><strong>Markdown (.md):</strong> Exportação completa para quem utiliza ferramentas de notas como Obsidian, Logseq ou VS Code.</li><li><strong>Importação de Transcrição (.md / .txt):</strong> Permite importar transcrições geradas fora do EchoBot, analisando oradores e timestamps para gerar diários técnicos e roteiros sem precisar do arquivo de áudio bruto.</li></ul><hr><h2 id="🎲-nota-sobre-vtts-foundry-vtt-roll20" tabindex="-1">🎲 Nota sobre VTTs (Foundry VTT &amp; Roll20) <a class="header-anchor" href="#🎲-nota-sobre-vtts-foundry-vtt-roll20" aria-label="Permalink to &quot;🎲 Nota sobre VTTs (Foundry VTT &amp; Roll20)&quot;">​</a></h2><blockquote><p><strong>Status de Desenvolvimento:</strong> A integração automatizada via módulo nativo de extensão JavaScript para o <strong>Foundry VTT</strong> e conexões diretas via protocolo MCP (Ouroboros) estão em fase de arquitetura e constam no nosso <a href="/EchoBotReleases/recursos/roadmap.html">Roadmap Oficial</a>. Atualmente, a interação com mesas virtuais é realizada através do áudio do Discord/WebRTC e exportação de textos.</p></blockquote>',24)])])}const g=a(s,[["render",i]]);export{p as __pageData,g as default};
